#!/bin/sh
# PreToolUse hook for Edit/Write tools.
# Blocks direct editing of auto-generated files.
# Reads JSON from stdin, extracts tool_input.file_path, and checks against block patterns.
# Exit 0 = allow, Exit 2 = block.
#
# xv: uv.lock is generated by uv. Change dependencies with `uv add` / `uv remove` / `uv lock`
# (run in src/) so that the lock file and pyproject.toml stay consistent.

# Read stdin
INPUT=$(cat)

# Shared JSON reader (jq -> python3 -> plutil). A guard that cannot read its input blocks (exit 2).
HOOK_JSON_LIB="$(dirname "$0")/lib/json.sh"
[ -r "$HOOK_JSON_LIB" ] || { echo "BLOCKED by validate-file-edit: $HOOK_JSON_LIB is missing; restore .claude/hooks/lib/json.sh from the repository" >&2; exit 2; }
# shellcheck source=lib/json.sh
. "$HOOK_JSON_LIB"
hook_json_require validate-file-edit

FILE_PATH=$(hook_json_get "$INPUT" tool_input.file_path)

if [ -z "$FILE_PATH" ]; then
  exit 0
fi

# Block editing of auto-generated files
case "$FILE_PATH" in
  uv.lock|*/uv.lock)
    echo "BLOCKED: uv.lock is generated by uv. Run \`uv add\` / \`uv remove\` / \`uv lock\` in src/ instead of editing it." >&2
    exit 2
    ;;
esac

exit 0
